function classifyGleifTerminalRun(run = {}, expectedBuildId = '') {
  const status = upper(run.status);
  const runId = String(run.id ?? '');
  const runUrl = runId ? `https://console.apify.com/actors/runs/${runId}` : 'https://console.apify.com/actors/runs';
  if (run.error || !status) return { ok: false, state: 'WORKFLOW_NODE_FAILED', run, runId, runUrl, reason: 'APIFY_RUN_NODE_ERROR' };
  if (status !== 'SUCCEEDED') return { ok: false, state: 'ACTOR_FAILED_OR_ABORTED', run, runId, runUrl, reason: `ACTOR_STATUS_${status}` };
