  if (billing?.mode !== 'ACTIVE_PPE' || billing?.pricingModel !== 'PAY_PER_EVENT') fail('PPE_PRICING_NOT_ACTIVE');
  const prices = billing.effectiveEventPricesUsd;
  const events = billing.events;
  if (!prices || typeof prices !== 'object' || !events || typeof events !== 'object') fail('AUTHORITATIVE_PPE_ACCOUNTING_MISSING');
  const chargedCounts = {};
  let total = 0;
  for (const [eventName, eventCounts] of Object.entries(events)) {
    const charged = Number(eventCounts?.charged ?? 0);
    if (!Number.isInteger(charged) || charged < 0) fail('INVALID_CHARGED_EVENT_COUNT');
    chargedCounts[eventName] = charged;
    if (!charged) continue;
    const price = Number(prices[eventName]);
    if (!Number.isFinite(price) || price < 0) fail('INVALID_EFFECTIVE_EVENT_PRICE');
    total += charged * price;
