  const datasetUrl = run.defaultDatasetId ? `https://console.apify.com/storage/datasets/${run.defaultDatasetId}` : runUrl;
  const buyerChargeUsd = Number(summary?.ppe?.actualBuyerChargeUsd);
  const coverageState = upper(summary.coverageState);
  const base = { run, summary, runId, runUrl, datasetUrl, buyerChargeUsd, coverageState };
