  const normalized = rows.filter((row) => row && typeof row === 'object' && Object.keys(row).length && !row.error);
  if (normalized.length !== Number(summary.deliveredRows)) return { ...base, state: 'WORKFLOW_NODE_FAILED', reason: 'DATASET_ROW_COUNT_MISMATCH', shouldWrite: false, sheetRows: [] };
