      if (seen.has(row.upsertKey)) fail('DUPLICATE_UPSERT_KEYS_IN_DATASET');
      seen.add(row.upsertKey);
      sheetRows.push(row);
    }
  } catch (error) {
    return { ...base, state: 'WORKFLOW_NODE_FAILED', reason: error.message, shouldWrite: false, sheetRows: [] };
  }
  if (!sheetRows.length) return { ...base, state: 'WORKFLOW_NODE_FAILED', reason: 'ZERO_ROWS_WITHOUT_VERIFIED_EMPTY', shouldWrite: false, sheetRows: [] };
  return {
    ...base,
    state: coverageState === 'CAPPED' ? 'CAPPED' : 'READY_TO_WRITE',
    reason: coverageState === 'CAPPED' ? 'BOUNDED_GLEIF_REGISTER_WRITTEN_WITH_CAP_DISCLOSED' : 'VERIFIED_GLEIF_REGISTER_READY',
    shouldWrite: true,
